import{_ as e,o as t,c as a,a3 as o}from"./chunks/framework.CCylkYel.js";const u=JSON.parse('{"title":"Simulator and scripts","description":"","frontmatter":{},"headers":[],"relativePath":"developers/simulator.md","filePath":"developers/simulator.md"}'),i={name:"developers/simulator.md"};function n(r,s,c,p,d,l){return t(),a("div",null,[...s[0]||(s[0]=[o(`<h1 id="simulator-and-scripts" tabindex="-1">Simulator and scripts <a class="header-anchor" href="#simulator-and-scripts" aria-label="Permalink to &quot;Simulator and scripts&quot;">​</a></h1><h2 id="loopback" tabindex="-1"><code>--loopback</code> <a class="header-anchor" href="#loopback" aria-label="Permalink to &quot;\`--loopback\`&quot;">​</a></h2><p><code>--loopback</code> runs the same protocol against a simulated S32 inside the s32 CLI process. No hardware needed. Use it to try commands, write examples and run CI. The s32 CLI never picks the simulator on its own: without <code>--loopback</code> it talks to your S32 on USB.</p><p>Every <code>--loopback</code> run prints <code>note: using the s32 simulator (--loopback), not your S32</code> on stderr; <code>-q</code> and <code>--json</code> leave it out.</p><ul><li><strong>Every run starts fresh</strong> with three projects (Project 1–3) and one card project. A <code>macro set</code> in one run is gone in the next. Chain steps in a <a href="./getting-started#interactive-session">REPL</a> or a script.</li><li><strong>Real devices.</strong> Every device type with its real parameters, defaults and ranges, as <code>schema --emit-schema-json</code> lists them. Values are rounded and clamped to each parameter&#39;s range, as on the S32. A range that follows a device&#39;s SYNC setting (Arpeggiator RATE, Delay DELAY TIME) is the full range here.</li></ul><h2 id="script" tabindex="-1"><code>--script</code> <a class="header-anchor" href="#script" aria-label="Permalink to &quot;\`--script\`&quot;">​</a></h2><p>One command per line. <code>#</code> starts a comment. A script does not prompt, and <code>--script</code> does not imply <code>--yes</code>: a command that <a href="./connecting#usb">asks first</a> needs <code>--yes</code> on the <code>s32</code> command line (<code>s32 --yes --script FILE</code>) or on its own line, otherwise that line fails with exit code 5 and the run stops. The run stops at the first line that fails and exits with that line&#39;s <a href="./commands/session#exit-codes">exit code</a>. <code>pause [MS]</code> waits (default 1000 ms).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --script</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session.script</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --usb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --script</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session.script</span></span></code></pre></div><p><code>session.script</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hello</span></span>
<span class="line"><span>list</span></span>
<span class="line"><span>macro get 1 1</span></span>
<span class="line"><span>macro set 5 2 mode=cc msb=74 channel=3</span></span>
<span class="line"><span>potname set 5 Cutoff</span></span></code></pre></div><p>Words in a script line split on spaces, with no quoting. Use names without spaces.</p><h2 id="json-in-scripts-and-the-repl" tabindex="-1">JSON in scripts and the REPL <a class="header-anchor" href="#json-in-scripts-and-the-repl" aria-label="Permalink to &quot;JSON in scripts and the REPL&quot;">​</a></h2><p>Put <code>--json</code> before <code>--script</code> or <code>repl</code> and every line that succeeds prints exactly one JSON object (NDJSON), with no echo and no banner:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;macro get 5 2\\nrack list\\nmacro set 5 2 channel=3\\n&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> j.script</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --script</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> j.script</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{&quot;pot&quot;:5,&quot;macro&quot;:2,&quot;mode&quot;:&quot;disabled&quot;,...}</span></span>
<span class="line"><span>{&quot;count&quot;:1,&quot;max&quot;:8,&quot;racks&quot;:[{&quot;index&quot;:1,&quot;id&quot;:100,&quot;bypass&quot;:&quot;off&quot;,&quot;in&quot;:&quot;yes&quot;,&quot;devices&quot;:1,&quot;name&quot;:&quot;Rack 1&quot;}]}</span></span>
<span class="line"><span>{&quot;pot&quot;:5,&quot;macro&quot;:2,&quot;mode&quot;:&quot;disabled&quot;,&quot;msb&quot;:0,&quot;lsb&quot;:0,&quot;channel&quot;:&quot;3&quot;,...}</span></span></code></pre></div><p>The third line is the read-back of <code>macro set</code>. A failing line prints one <a href="./commands/session#errors">JSON error</a> on stderr with <code>line</code> and <code>text</code>, and the script stops with that line&#39;s exit code; in a REPL the session goes on. The rest is in <a href="./commands/session#json-output">JSON output</a>.</p><h2 id="test-fixtures" tabindex="-1">Test fixtures <a class="header-anchor" href="#test-fixtures" aria-label="Permalink to &quot;Test fixtures&quot;">​</a></h2><p><code>S32_LOOPBACK_DROP_AFTER_WRITE=N</code> makes the simulator answer nothing after the Nth write has been answered Ok, so the next request times out (exit code 3). It tests what a program does when a change landed but could not be confirmed: <code>S32_LOOPBACK_DROP_AFTER_WRITE=1 s32 --loopback macro set 5 2 channel=3 --json</code> prints one error with <code>&quot;class&quot;:&quot;link&quot;</code> and <code>&quot;applied&quot;:true</code>.</p>`,18)])])}const k=e(i,[["render",n]]);export{u as __pageData,k as default};
